import { Component, signal } from '@angular/core';
import { CurrencyPipe, DatePipe, DecimalPipe, PercentPipe, TitleCasePipe, UpperCasePipe } from '@angular/common';

@Component({
  selector: 'app-invoice',
  imports: [CurrencyPipe, DatePipe, DecimalPipe, PercentPipe, TitleCasePipe, UpperCasePipe],
  template: `
    <p>{{ customer() | titlecase }}</p>
    <p>{{ status() | uppercase }}</p>
    <p>{{ issued() | date:'longDate' }}</p>
    <p>{{ issued() | date:'EEEE' }}</p>
    <p>{{ amount() | currency:'EUR' }}</p>
    <p>{{ amount() | number:'1.0-0' }}</p>
    <p>{{ discount() | percent:'1.0-1' }}</p>
  `,
})
export class Invoice {
  readonly customer = signal('ada lovelace');
  readonly status = signal('paid');
  readonly issued = signal(new Date(2026, 4, 28));
  readonly amount = signal(1234.56);
  readonly discount = signal(0.125);
}

import { Pipe, PipeTransform } from '@angular/core';

@Pipe({ name: 'truncate' })
export class TruncatePipe implements PipeTransform {
  transform(value: string, max = 20, suffix = '...'): string {
    return value.length <= max ? value : value.slice(0, max).trimEnd() + suffix;
  }
}

import { Directive, input, signal } from '@angular/core';

@Directive({
  selector: '[appHighlight]',
  host: {
    '[style.background-color]': 'hovering() ? color() : null',
    '(mouseenter)': 'hovering.set(true)',
    '(mouseleave)': 'hovering.set(false)',
  },
})
export class Highlight {
  readonly color = input('yellow', {
    alias: 'appHighlight',
    transform: (value: string) => value || 'yellow',
  });
  readonly hovering = signal(false);
}

